def make(i, row):
    tag, prompt, opts, answer, reason = row
    target_letters=['A','B','C','D','B','C','D','A','C','B']
    aid=target_letters[i-1]
    distractors=[t for t in opts if t != answer]
    ordered=[]; di=0
    for letter in ['A','B','C','D']:
        if letter == aid: ordered.append(answer)
        else: ordered.append(distractors[di]); di += 1
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(ordered)]
    steps = [f'讀題定位：圈出「{tag}」以及排放、碳吸收、暴露、脆弱度、恢復或公平條件。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合減緩／調適與氣候治理判斷。', '排除誘答：分清減緩與調適、短期工程與長期韌性、平均值與群體差異，不把一項措施當成萬能解法。', '最後回查：確認資料時間尺度、監測回饋與受影響群體都被納入結論。']
    return {'id': f'question-science-content-nb-iv-3-{i}', 'subject': 'science', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-science-content-nb-iv-3'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': URL, 'sourceLocator': '公立國中段考自然科；研究氣候變遷減緩、調適、韌性、公平、成本效益與政策證據的能力方向。', 'authoringNote': '依官方課綱 KG 與公立國中公開試題能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-08', 'lessonId': 'lesson-science-content-nb-iv-3', 'examPatternRefs': [{'url': URL, 'title': '公立國中段考自然科；僅研究題型與能力方向，未複製原題。', 'year': '114', 'subject': 'science', 'locator': '氣候變遷的減緩與調適', 'observedPattern': '能力方向研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'}], 'solutionStrategy': '先分辨減緩與調適，再比較排放、風險、長期效益與公平影響，最後以監測資料與情境不確定性修正方案。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-science-content-nb-iv-3-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
print('rewrote', len(DATA), 'questions')
